<?php
namespace App\Policies;use App\Models\TenantCustomer;use App\Models\User;
final class TenantCustomerPolicy{private function platform(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','COMPLIANCE_ADMIN'])->exists();}private function tenant(User$u,string$id):bool{return$this->platform($u)||$u->memberships()->where(['tenant_id'=>$id,'status'=>'ACTIVE'])->whereIn('role_code',['BROKER_ADMIN','BROKER_STAFF'])->exists();}public function viewAny(User$u):bool{return$u->memberships()->where('status','ACTIVE')->exists();}public function view(User$u,TenantCustomer$c):bool{return$this->tenant($u,$c->tenant_id);}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,TenantCustomer$c):bool{return$this->tenant($u,$c->tenant_id);}public function delete(User$u,TenantCustomer$c):bool{return false;}}
